		connect(b.MouseButton1Click, function()
			lib:_closePopups()
			onClick()
		end)
	end

	--------------------------------------------------------------------
	-- window state: minimize / maximize / hide
	--------------------------------------------------------------------
	local minimized, maximized = false, false
	local normalPos, normalSize

	local function refresh()
		win.Visible = lib.Toggled and not minimized
		taskbar.Visible = lib.Toggled and useTaskbar
		taskGrad.Color = seq(win.Visible and G.TaskBtnOn or G.TaskBtn)
		lib._notifs.Position = ud(1, -6, 1, -(taskbar.Visible and TASK_H or 0) - 2)
		sm.Position = ud(0, 0, 1, -(taskbar.Visible and TASK_H or 0))
	end

	function W:Minimize() minimized = true; lib:_closePopups(); refresh() end
	function W:Restore() minimized = false; refresh() end
	function W:ToggleMaximize()
		if maximized then
			win.Position, win.Size = normalPos, normalSize
			maximized = false
		else
			normalPos, normalSize = win.Position, win.Size
			local s = root.AbsoluteSize
			win.Position = px(0, 0)
			win.Size = px(s.X, s.Y - (taskbar.Visible and TASK_H or 0))
			maximized = true
		end
		maxIcon.Visible = not maximized
		restoreIcon.Visible = maximized
	end

	function lib:Toggle(state)
		if state == nil then state = not self.Toggled end
		self.Toggled = state
		self:_closePopups()
		if self._tip then self._tip.Visible = false end
		refresh()
	end

	function lib:SetTaskbar(on)
		useTaskbar = on and true or false
		if not useTaskbar and minimized then minimized = false end
		refresh()
	end

	local warnedClose = false
	connect(closeBtn.MouseButton1Click, function()
		W:Minimize()
		if not warnedClose then
			warnedClose = true
			lib:Notify(title, "Still running. Click the taskbar button to bring it back, or use Turn Off in the Start menu to unload.", 6)
		end
	end)
	connect(minBtn.MouseButton1Click, function() W:Minimize() end)
	connect(maxBtn.MouseButton1Click, function() W:ToggleMaximize() end)
	connect(taskBtn.MouseButton1Click, function()
		if win.Visible then W:Minimize() else W:Restore() end
	end)
	connect(trayIcon.MouseButton1Click, function()
		if win.Visible then W:Minimize() else W:Restore() end
	end)
	connect(startBtn.MouseButton1Click, function()
		if sm.Visible then
			lib:_closePopups()
		else
			sm.Visible = true
			startShade.BackgroundColor3 = Theme.Black
			startShade.BackgroundTransparency = 0.8
			lib:_openPopup(smPopup)
		end
	end)
	connect(startBtn.MouseEnter, function()
		if not sm.Visible then startShade.BackgroundColor3 = Theme.White; startShade.BackgroundTransparency = 0.85 end
	end)
	connect(startBtn.MouseLeave, function()
		if not sm.Visible then startShade.BackgroundTransparency = 1 end
	end)

	-- right column + footer of the start menu
	smItem(smRight, "Control Panel", "6E8FC9", 16, Theme.StartBlue, true, function()
		for _, t in ipairs(W.Tabs) do
			if t.Name:lower():find("setting") then W:Restore(); t:Select(); return end
		end
	end)
	smItem(smRight, "Help and Support", "2AA5B5", 16, Theme.StartBlue, true, function()
		lib:Notify("Help", keyName(lib.ToggleKey) .. " hides everything. The X button only minimizes. Turn Off unloads the script.", 7)
	end)
	smItem(smRight, "Hide Window", "8A8A8A", 16, Theme.StartBlue, true, function() W:Minimize() end)

	footerButton(-172, "Log Off", "E9A23B", function(ic)
		segment(ic, 5, 11, 15, 11, 2, Theme.White)
		segment(ic, 12, 7, 16, 11, 2, Theme.White)
		segment(ic, 12, 15, 16, 11, 2, Theme.White)
	end, function() lib:Toggle(false) end)
	footerButton(-88, "Turn Off", "D9442B", function(ic)
		new("Frame", { Parent = ic, Position = px(5, 6), Size = px(12, 12), BackgroundTransparency = 1, corner(6), stroke(Theme.White, 2) })
		box(ic, px(8, 2), px(6, 6), hex("D9442B"))
		box(ic, px(10, 3), px(2, 8), Theme.White)
	end, function() lib:Unload() end)

	--------------------------------------------------------------------
	-- dragging + resizing
	--------------------------------------------------------------------
	local dragging, resizing = false, false
	local dragStart, startPos, startSize
	local lastClick = 0

	connect(titleBar.InputBegan, function(input)
		if not isPress(input) then return end
		for _, h in ipairs(captionHovers) do
			if h.hovered then return end
		end
		local now = os.clock()
		if now - lastClick < 0.3 then
			lastClick = 0
			W:ToggleMaximize()
			return
		end
		lastClick = now
		if maximized then return end
		dragging = true
		local rel = win.AbsolutePosition - root.AbsolutePosition
		dragStart, startPos = input.Position, px(rel.X, rel.Y)
	end)
	connect(grip.InputBegan, function(input)
		if isPress(input) and not maximized then
			resizing = true
			dragStart, startSize = input.Position, win.AbsoluteSize
		end
	end)
	connect(UIS.InputChanged, function(input)
		if not isMove(input) then return end
		if dragging then
			local d = input.Position - dragStart
			local s = root.AbsoluteSize
			-- keep the title bar out from under Roblox's own topbar buttons
			local topInset = GuiService:GetGuiInset().Y
			local x = math.clamp(startPos.X.Offset + d.X, -win.AbsoluteSize.X + 100, s.X - 100)
			local y = math.clamp(startPos.Y.Offset + d.Y, topInset, math.max(topInset, s.Y - TITLE_H))
			win.Position = px(x, y)
		elseif resizing then
			local d = input.Position - dragStart
			win.Size = px(math.max(MIN_W, startSize.X + d.X), math.max(MIN_H, startSize.Y + d.Y))
		end
	end)
	connect(UIS.InputEnded, function(input)
		if isPress(input) then dragging, resizing = false, false end
	end)

	-- click-outside closes popups, toggle key hides everything
	connect(UIS.InputBegan, function(input, gp)
		if isPress(input) then
			for i = #lib._popups, 1, -1 do
				local p = lib._popups[i]
				if not p.hovered() then
					p.close()
					table.remove(lib._popups, i)
				end
			end
		end
		if not gp and not lib._binding and input.KeyCode == lib.ToggleKey then
			lib:Toggle()
		end
	end)

	--------------------------------------------------------------------
	-- tabs
	--------------------------------------------------------------------
	function W:AddTab(name)
		local tab = { Name = name }
		local index = #W.Tabs + 1

		local slotW = textWidth(name) + 14
		local slot = new("Frame", { Parent = strip, BackgroundTransparency = 1, Size = px(slotW, 22), LayoutOrder = index })

		-- the window can never be narrower than its tab strip (16 strip inset + 6 frame + 4 spare)
		tabsWidth += slotW
		MIN_W = math.max(MIN_W, tabsWidth + 26)
		if win.Size.X.Offset < MIN_W then
			win.Size = px(MIN_W, win.Size.Y.Offset)
			if win.Position.X.Scale == 0.5 then
				win.Position = ud(0.5, -math.floor(MIN_W / 2), win.Position.Y.Scale, win.Position.Y.Offset)
			end
		end
		local btn = new("TextButton", { Parent = slot, Position = px(0, 2), Size = ud(1, 0, 0, 19) })
		local bg = new("Frame", { Parent = btn, Position = px(1, 1), Size = ud(1, -2, 1, -1), BackgroundColor3 = Theme.White })
		local bgGrad = gradient(G.TabIdle); bgGrad.Parent = bg
		box(btn, px(2, 0), ud(1, -4, 0, 1), Theme.PanelBorder)
		box(btn, px(0, 2), ud(0, 1, 1, -2), Theme.PanelBorder)
		box(btn, ud(1, -1, 0, 2), ud(0, 1, 1, -2), Theme.PanelBorder)
		box(btn, px(1, 1), px(1, 1), Theme.PanelBorder)
		box(btn, ud(1, -2, 0, 1), px(1, 1), Theme.PanelBorder)
		local hl = new("Frame", { Parent = btn, BackgroundTransparency = 1, Size = ud(1, 0, 0, 3), Visible = false })
		box(hl, px(2, 0), ud(1, -4, 0, 1), Theme.TabTop)
		box(hl, px(1, 1), ud(1, -2, 0, 2), Theme.TabTopLight)
		new("TextLabel", { Parent = btn, Position = px(0, 1), Size = ud(1, 0, 1, 0), Text = name })

		local page = new("Frame", { Parent = pages, BackgroundTransparency = 1, Size = ud(1, 0, 1, 0), Visible = false })
		local function column(isLeft)
			local col = new("ScrollingFrame", {
				Parent = page, BackgroundTransparency = 1,
				Position = isLeft and px(0, 0) or ud(0.5, 0, 0, 0), Size = ud(0.5, 0, 1, 0),
				CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y,
				ScrollBarThickness = 4, ScrollBarImageColor3 = hex("A9B8D9"), VerticalScrollBarInset = Enum.ScrollBarInset.Always,
				pad(14, isLeft and 6 or 12, 10, isLeft and 12 or 6), list(Enum.FillDirection.Vertical, 18),
			})
			connect(col:GetPropertyChangedSignal("CanvasPosition"), function() lib:_closePopups() end)
			return col
		end
		tab._left, tab._right = column(true), column(false)

		local active = false
		function tab:_setActive(on)
			active = on
			page.Visible = on
			slot.ZIndex = on and 2 or 1
			hl.Visible = on
			if on then
				btn.Position, btn.Size = px(-2, 0), ud(1, 4, 0, 22)
				bgGrad.Enabled = false
				bg.BackgroundColor3 = Theme.Panel
			else
				btn.Position, btn.Size = px(0, 2), ud(1, 0, 0, 19)
				bgGrad.Enabled = true
				bg.BackgroundColor3 = Theme.White
			end
		end
		function tab:Select()
			for _, t in ipairs(W.Tabs) do t:_setActive(t == tab) end
			lib:_closePopups()
		end
		connect(btn.MouseButton1Click, function() tab:Select() end)
		connect(btn.MouseEnter, function() if not active then hl.Visible = true end end)
		connect(btn.MouseLeave, function() if not active then hl.Visible = false end end)

		function tab:AddGroup(gname, side)
			local col = (side == "Right") and tab._right or tab._left
			local frame = new("Frame", {
				Parent = col, BackgroundTransparency = 1, Size = ud(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
				LayoutOrder = #col:GetChildren(), corner(3), stroke(Theme.GroupBorder),
			})
			new("TextLabel", {
				Parent = frame, Position = px(7, -8), Size = px(textWidth(gname) + 6, 15), Text = gname,
				TextColor3 = Theme.GroupText, BackgroundTransparency = 0, BackgroundColor3 = Theme.PanelMid, ZIndex = 2,
			})
			local content = new("Frame", {
				Parent = frame, BackgroundTransparency = 1, Size = ud(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
				pad(14, 10, 10, 10), list(Enum.FillDirection.Vertical, 7),
			})
			return setmetatable({ _content = content, _order = 0 }, Group)
		end

		table.insert(W.Tabs, tab)
		-- grow the start menu so every tab fits (header 58 + footer 40 + padding 12, 30px per item)
		sm.Size = px(SM_W, math.max(SM_H, 110 + #W.Tabs * 30))
		smItem(smLeft, name, palette[(index - 1) % #palette + 1], 22, Theme.Text, false, function()
			W:Restore()
			tab:Select()
		end)
		if index == 1 then tab:Select() end
		return tab
	end

	refresh()
	return W
end

------------------------------------------------------------------------
function Library:OnUnload(fn) table.insert(self._onUnload, fn) end

function Library:Unload()
	if self.Unloaded then return end
	self.Unloaded = true
	for _, fn in ipairs(self._onUnload) do pcall(fn) end
	for _, c in ipairs(self._conns) do pcall(function() c:Disconnect() end) end
	self._conns = {}
	if self.Gui then self.Gui:Destroy() end
	if env.__xpui == self then env.__xpui = nil end
end

return Library

end)()

--[[
	xpware - Murder Mystery 2
	Engine: Roblox client (executor)  |  Language: Luau

	Where the library comes from:
	  - bundled by build.ps1: `Library` is defined above this file
	  - Roblox Studio: ReplicatedStorage.xpware.xpui ModuleScript
	  - executor, unbundled: xpware/xpui.lua in the executor's workspace folder

	Executor functions used when present (each feature says so if one is missing):
	  firetouchinterest  - knife aura, kill all, coin/gun touches
	  hookmetamethod, getnamecallmethod, checkcaller, newcclosure - silent aim, throw assist
	  Drawing            - tracers
	  readfile/writefile/isfile/makefolder/delfile - configs
	  setclipboard, game:HttpGet - copy job id, server hop
]]

local Library = Library
if not Library then
	local folder = game:GetService("ReplicatedStorage"):FindFirstChild("xpware")
	local module = folder and folder:FindFirstChild("xpui")
	if module then
		Library = require(module)
	else
		Library = loadstring(readfile("xpware/xpui.lua"))()
	end
end

local NAME = "xpware"
local VERSION = "0.2"

------------------------------------------------------------------------
-- Services / shared state
------------------------------------------------------------------------
local Players           = game:GetService("Players")
local RunService        = game:GetService("RunService")
local UIS               = game:GetService("UserInputService")
local TweenService      = game:GetService("TweenService")
local Lighting          = game:GetService("Lighting")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TeleportService   = game:GetService("TeleportService")
local HttpService       = game:GetService("HttpService")
local TextChatService   = game:GetService("TextChatService")
local GuiService        = game:GetService("GuiService")

local LP = Players.LocalPlayer
local Flags = Library.Flags
local Options = Library.Options
local GENV = (typeof(getgenv) == "function" and getgenv()) or _G

local function has(fn) return typeof(fn) == "function" end
local touch = has(firetouchinterest) and firetouchinterest or nil

local conns, cleanups = {}, {}
local function on(signal, fn)
	local c = signal:Connect(fn)
	table.insert(conns, c)
	return c
end
local function onUnload(fn) table.insert(cleanups, fn) end
local function running() return not Library.Unloaded end
local function notify(text, title, dur) Library:Notify(title or NAME, text, dur or 4) end

Library:OnUnload(function()
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	for i = #cleanups, 1, -1 do pcall(cleanups[i]) end
end)

local function cam() return workspace.CurrentCamera end

------------------------------------------------------------------------
-- Character helpers
------------------------------------------------------------------------
local function humOf(p) local c = p and p.Character; return c and c:FindFirstChildOfClass("Humanoid") end
local function rootOf(p) local c = p and p.Character; return c and c:FindFirstChild("HumanoidRootPart") end
local function isAlive(p) local h = humOf(p); return h ~= nil and h.Health > 0 and rootOf(p) ~= nil end
local function myRoot() return rootOf(LP) end
local function myHum() return humOf(LP) end

local function teleport(cf)
	local c, r = LP.Character, myRoot()
	if not (c and r) then return false end
	r.AssemblyLinearVelocity = Vector3.zero
	c:PivotTo(cf)
	return true
end

local function partOf(inst)
	if not inst then return nil end
	if inst:IsA("BasePart") then return inst end
	if inst:IsA("Model") then return inst.PrimaryPart or inst:FindFirstChildWhichIsA("BasePart", true) end
	return inst:FindFirstChildWhichIsA("BasePart", true)
end

local function touchPart(part)
	local r = myRoot()
	if touch and r and part then
		pcall(touch, r, part, 0)
		pcall(touch, r, part, 1)
	end
end

local function findPlayer(name)
	if type(name) ~= "string" or name == "" then return nil end
	name = name:lower()
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name:lower() == name or p.DisplayName:lower() == name then return p end
	end
	for _, p in ipairs(Players:GetPlayers()) do
		if p.Name:lower():sub(1, #name) == name or p.DisplayName:lower():sub(1, #name) == name then return p end
	end
end

local function otherNames()
	local t = {}
	for _, p in ipairs(Players:GetPlayers()) do
		if p ~= LP then table.insert(t, p.Name) end
	end
	table.sort(t, function(a, b) return a:lower() < b:lower() end)
	return t
end

------------------------------------------------------------------------
-- MM2 game state: map, lobby, dropped gun, roles
------------------------------------------------------------------------
local State = { map = nil, lobbyBox = nil, gun = nil, data = {} }

local ROLE_COLORS = {
	Murderer = Color3.fromRGB(255, 59, 59),
	Sheriff  = Color3.fromRGB(59, 139, 255),
	Hero     = Color3.fromRGB(255, 200, 59),
	Innocent = Color3.fromRGB(76, 217, 100),
}
local GUN_COLOR = Color3.fromRGB(170, 90, 255)
local COIN_COLOR = Color3.fromRGB(255, 215, 0)

local function findMap()
	for _, m in ipairs(workspace:GetChildren()) do
		if m.Name ~= "Lobby" and (m:IsA("Model") or m:IsA("Folder")) and m:FindFirstChild("CoinContainer") then
			return m
		end
	end
	for _, m in ipairs(workspace:GetChildren()) do
		if m.Name ~= "Lobby" and m:IsA("Model") and m:FindFirstChild("Spawns") then return m end
	end
end

local function updateLobbyBox()
	local lobby = workspace:FindFirstChild("Lobby")
	if lobby and lobby:IsA("Model") then
		local ok, cf, size = pcall(lobby.GetBoundingBox, lobby)
		if ok then State.lobbyBox = { cf = cf, half = size / 2 + Vector3.new(10, 60, 10) } return end
	end
	State.lobbyBox = nil
end

local function inLobby(p)
	local r, box = rootOf(p), State.lobbyBox
	if not (r and box) then return false end
	local rel = box.cf:PointToObjectSpace(r.Position)
	return math.abs(rel.X) <= box.half.X and math.abs(rel.Y) <= box.half.Y and math.abs(rel.Z) <= box.half.Z
end

local function hasTool(p, name)
	local c, b = p.Character, p:FindFirstChildOfClass("Backpack")
	return (c and c:FindFirstChild(name)) or (b and b:FindFirstChild(name)) or nil
end

local function dataOf(p)
	local d = State.data[p.Name]
	return type(d) == "table" and d or nil
end

local function roleOf(p)
	if hasTool(p, "Knife") then return "Murderer" end
	local d = dataOf(p)
	local r = d and d.Role
	if hasTool(p, "Gun") then return r == "Hero" and "Hero" or "Sheriff" end
	if r == "Murderer" or r == "Sheriff" or r == "Hero" then return r end
	return "Innocent"
end

-- alive, on the map, and not marked dead by the game's own player data
local function inRound(p)
	if not State.map or not isAlive(p) then return false end
	local d = dataOf(p)
	if d and (d.Dead or d.Killed) then return false end
	return not inLobby(p)
end

local function findRole(role)
	for _, p in ipairs(Players:GetPlayers()) do
		if isAlive(p) and roleOf(p) == role then return p end
	end
end
local function findSheriff() return findRole("Sheriff") or findRole("Hero") end

local function isCoinLive(c)
	if not (c and c.Parent and c:IsA("BasePart")) then return false end
	local v = c:FindFirstChild("CoinVisual")
	if v and v:IsA("BasePart") and v.Transparency >= 1 then return false end
	return true
end

local function liveCoins()
	local list = {}
	local cc = State.map and State.map:FindFirstChild("CoinContainer")
	if cc then
		for _, c in ipairs(cc:GetChildren()) do
			if isCoinLive(c) then table.insert(list, c) end
		end
	end
	return list
end

