------------------------------------------------------------------------
local espFolder = Instance.new("Folder")
espFolder.Name = HttpService:GenerateGUID(false)
if not pcall(function() espFolder.Parent = (Library.Gui and Library.Gui.Parent) or game:GetService("CoreGui") end) then
